import { readFileSync, writeFileSync } from "node:fs";
const files = [
  "migrations/001_initial.sql",
  "migrations/002_releases.sql",
  "migrations/003_stores.sql",
  "migrations/004_release_review.sql",
  "migrations/005_event_images.sql",
  "migrations/006_event_benefits.sql",
  "migrations/007_translated_rules.sql",
  "seed.sql",
  "releases-seed.sql",
  "stores-seed.sql",
];
const sql = [
  "-- NEW / EMPTY SUPABASE PROJECT ONLY. Run once in SQL Editor.\n-- Existing projects: apply only missing migrations; do not run this bundle.\n-- Generated by node scripts/generate-setup-sql.mjs after generate-seed.mjs.\n",
  ...files.map(
    (file) =>
      `-- BEGIN FILE: ${file}\n${readFileSync(`supabase/${file}`, "utf8")}\n-- END FILE: ${file}\n`,
  ),
];
writeFileSync("supabase/setup-new-project.sql", sql.join("\n"));
console.log(
  "Generated supabase/setup-new-project.sql (new projects only; no remote database changed).",
);
